              cover: typeof p.cover === 'string' ? p.cover.slice(0, 500) : '',
            })).filter((p) => p.prompt)
            writeJson(res, 200, { prompts })
          } catch (e) { writeJson(res, 200, { prompts: [], error: '解析失败: ' + e.message }) }
        })
      },
    },
