            apiPost(API.imageFile, { name: name }).then(function (r) { if (r.dataUrl) img.src = r.dataUrl })
          })
          preview.appendChild(grid)
        }
        function retryLog(l) {
          st.prompt = l.prompt
          st.refs = []
          if (l.params) {
            if (l.params.size && /^\d+x\d+$/.test(l.params.size)) {
